<?php
namespace Joomla\Component\Academy\Administrator\Controller;
defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\CMS\MVC\Controller\BaseController;use Joomla\CMS\Router\Route;use Joomla\CMS\Session\Session;use Joomla\Database\DatabaseInterface;
final class EmailtemplateController extends BaseController{public function save():void{Session::checkToken()or jexit('Invalid token');$app=Factory::getApplication();if(!$app->getIdentity()->authorise('core.manage','com_academy'))throw new \RuntimeException('Not authorised',403);$in=$app->getInput();$id=$in->post->getInt('id');$row=(object)['id'=>$id?:null,'title'=>trim($in->post->getString('title')),'subject'=>trim($in->post->getString('subject')),'body'=>$in->post->get('body','','raw'),'created'=>$in->post->getString('created')?:Factory::getDate()->toSql()];if($row->title===''||$row->subject===''||trim(strip_tags($row->body))==='')throw new \RuntimeException('Name, subject, and message are required.',400);$db=Factory::getContainer()->get(DatabaseInterface::class);$id?$db->updateObject('#__academy_email_templates',$row,'id'):$db->insertObject('#__academy_email_templates',$row,'id');$app->enqueueMessage('Email template saved.');$app->redirect(Route::_('index.php?option=com_academy&view=emailtemplates',false));}public function cancel():void{Factory::getApplication()->redirect(Route::_('index.php?option=com_academy&view=emailtemplates',false));}}
